#!/usr/bin/env python3
# gen_intl.py — generates src/ojs/intl_data.c from CLDR JSON.
# CLDR data is under the Unicode License (data, not code) — same class as the
# UCD tables generated by tools/gen_unicode.py. Owner-approved exception.
#
# Usage: python3 tools/gen_intl.py            (expects build-host/cldr/ extracted)
#
# Covered services: Intl.Locale (canonicalization + likely subtags),
# Intl.PluralRules (cardinal+ordinal), Intl.NumberFormat (decimal/percent/
# currency symbols+names, standard/scientific/compact), Intl.DateTimeFormat
# (gregorian, styles + components), Intl.ListFormat, Intl.RelativeTimeFormat.
import json, os, re

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CLDR = os.path.join(ROOT, "build-host", "cldr")

LOCALES = sorted(set([
    "en", "en-AU", "en-CA", "en-GB", "en-IN", "de", "de-AT", "de-CH",
    "fr", "fr-CA", "fr-CH", "es", "es-MX", "es-419", "it", "pt", "pt-PT",
    "ru", "uk", "pl", "nl", "nl-BE", "sv", "da", "nb", "fi", "cs", "sk",
    "el", "tr", "hu", "ro", "bg", "he", "ar", "fa", "hi", "th", "vi",
    "id", "zh", "zh-Hant", "ja", "ko"]))

NUMSYS = ["latn", "arab", "arabext", "beng", "deva", "thai", "hanidec", "fullwide"]

CURRENCIES = ["USD", "EUR", "GBP", "JPY", "CNY", "INR", "RUB", "UAH", "BRL",
              "MXN", "CAD", "AUD", "NZD", "CHF", "SEK", "NOK", "DKK", "PLN",
              "CZK", "HUF", "RON", "BGN", "TRY", "ILS", "SAR", "AED", "QAR",
              "EGP", "ZAR", "KRW", "HKD", "TWD", "SGD", "THB", "VND", "IDR",
              "PHP", "MYR", "CLP", "COP", "ARS", "PEN", "ISK", "RSD", "KES",
              "NGN", "PKR", "BDT", "LKR"]

UNITS = ["meter", "kilometer", "centimeter", "millimeter", "inch", "foot",
         "yard", "mile", "acre", "liter", "milliliter", "gallon",
         "gram", "kilogram", "tonne", "pound", "ounce",
         "second", "minute", "hour", "day", "week", "month", "year", "millisecond",
         "bit", "kilobit", "byte", "kilobyte", "megabyte", "gigabyte", "terabyte", "petabyte",
         "celsius", "fahrenheit", "kelvin",
         "kilometer-per-hour", "mile-per-hour", "meter-per-second",
         "square-meter", "square-kilometer", "percent"]

# Intl unit ids ("meter") -> CLDR keys are category-prefixed ("length-meter")
UNIT_PREFIX = ["length-", "area-", "volume-", "mass-", "duration-", "digital-",
               "temperature-", "speed-", "concentr-"]
def unit_keys(uid):
    return [p + uid for p in UNIT_PREFIX] + [uid]

RTF_FIELDS = ["year", "quarter", "month", "week", "day", "hour", "minute", "second"]

ALLOWED_SYMS = set("yYuMLdEechHKkmsSabzG")
CAT = {"zero": 0, "one": 1, "two": 2, "few": 3, "many": 4, "other": 5}
CATN = 5

pool = {}
pool_buf = []
def po(s):
    if s in pool: return pool[s]
    off = sum(len(b) + 1 for b in pool_buf)
    pool[s] = off
    pool_buf.append(s.encode("utf-8"))
    return off

def parr(items):
    """offset of the first of N strings appended consecutively (no dedup)"""
    if not items: return 0xFFFF
    off = sum(len(b) + 1 for b in pool_buf)
    for it in items: pool_buf.append(it.encode("utf-8"))
    return off

skels = {}
def sk(s):
    if s not in skels: skels[s] = len(skels)
    return skels[s]

rulesets = {}
rs_rows = []   # (mask, [pool offsets in zero..many order, present only])
def ruleset(catmap):
    kept = [(i, catmap[c].split(" @")[0].strip()) for i, c in enumerate(("zero", "one", "two", "few", "many"))
            if catmap.get(c)]
    if not kept: return 0xFFFF
    key = "|".join(f"{i}:{e}" for i, e in kept)
    if key in rulesets: return rulesets[key]
    mask = 0
    offs = []
    for i, e in kept:
        mask |= 1 << i
        offs.append(po(e))
    idx = len(rs_rows)
    rs_rows.append((mask, offs))
    rulesets[key] = idx
    return idx

cpairs = []
def cpair(cat, pat):
    cpairs.append((cat, po(pat)))
    return len(cpairs) - 1

cgrps = []
def cgrp(pairs):
    if not pairs: return 0xFFFF
    off = len(cpairs)
    for c, p in pairs: cpairs.append((c, po(p)))
    cgrps.append((off, len(pairs)))
    return len(cgrps) - 1

def cgrp_view(idx):
    """(off, n) of a cgrp index, for direct emission"""
    if idx == 0xFFFF: return (0xFFFF, 0)
    return cgrps[idx]

def load(p):
    with open(os.path.join(CLDR, p), encoding="utf-8") as f:
        return json.load(f)

def syms(j):
    order = ["decimal", "group", "percentSign", "plusSign", "minusSign",
             "exponential", "perMille", "list"]
    return [j.get(k, "") for k in order]

def hc_of(pat):
    if "K" in pat: return 0
    if "h" in pat: return 1
    if "H" in pat: return 2
    if "k" in pat: return 3
    return 2

def pattern_chars(p):
    out, i = [], 0
    while i < len(p):
        c = p[i]
        if c == "'":
            j = p.find("'", i + 1)
            i = (j + 1) if j >= 0 else len(p)
            continue
        if c.isalpha(): out.append(c)
        i += 1
    return out

def ok_pattern(p):
    i = 0
    while i < len(p):
        c = p[i]
        if c == "'":
            j = p.find("'", i + 1)
            if j < 0: return False
            i = j + 1
            continue
        if c.isalpha() and c not in ALLOWED_SYMS: return False
        i += 1
    return True

# ---------------------------------------------------------------- supplemental
sup = load("cldr-core/supplemental/likelySubtags.json")["supplemental"]["likelySubtags"]
alias_all = load("cldr-core/supplemental/aliases.json")["supplemental"]["metadata"]["alias"]
plurals = load("cldr-core/supplemental/plurals.json")["supplemental"]["plurals-type-cardinal"]
ordinals = load("cldr-core/supplemental/ordinals.json")["supplemental"]["plurals-type-ordinal"]
nsys_all = load("cldr-core/supplemental/numberingSystems.json")["supplemental"]["numberingSystems"]
curfrac = load("cldr-core/supplemental/currencyData.json")["supplemental"]["currencyData"]["fractions"]

def alias_entries(group):
    out = []
    for k, v in sorted(alias_all.get(group, {}).items()):
        if v.get("_reason") not in ("deprecated", "overlong"): continue
        rep = v.get("_replacement", "")
        if not rep or not re.match(r"^[A-Za-z0-9_]+$", rep): continue
        if rep.count("_") + 1 > 3: continue
        out.append((k.lower(), rep.replace("_", "-")))
    return out

lang_alias = alias_entries("languageAlias")
terr_alias = alias_entries("territoryAlias")
scr_alias = alias_entries("scriptAlias")

# ---------------------------------------------------------------- per-locale data
locales = []
miss = []
for tag in LOCALES:
    nd = f"cldr-numbers-full/main/{tag}"
    if not os.path.isdir(os.path.join(CLDR, nd)):
        miss.append(tag); continue
    num = load(nd + "/numbers.json")["main"][tag]["numbers"]
    dts = load(f"cldr-dates-full/main/{tag}/ca-gregorian.json")["main"][tag]["dates"]["calendars"]["gregorian"]
    try:
        msc = load(f"cldr-misc-full/main/{tag}/listPatterns.json")["main"][tag]["listPatterns"]
    except FileNotFoundError:
        msc = None
    try:
        unt = load(f"cldr-units-full/main/{tag}/units.json")["main"][tag]["units"]
    except FileNotFoundError:
        unt = None
    try:
        fld = load(f"cldr-dates-full/main/{tag}/dateFields.json")["main"][tag]["dates"]["fields"]
    except FileNotFoundError:
        fld = None
    try:
        curs = load(nd + "/currencies.json")["main"][tag]["numbers"]["currencies"]
    except FileNotFoundError:
        curs = {}

    # ICU's default for th/ar/hi is the NATIVE system (otherNumberingSystems
    # .native), which is what the Intl tests expect; defaultNumberingSystem is
    # latn in CLDR 49 for those
    nu = num.get("otherNumberingSystems", {}).get("native") or num.get("defaultNumberingSystem", "latn")
    if nu not in NUMSYS: nu = "latn"
    sym = num[f"symbols-numberSystem-{nu}"]
    std = num[f"decimalFormats-numberSystem-{nu}"]["standard"]
    pct = num[f"percentFormats-numberSystem-{nu}"]["standard"]
    sci = num[f"scientificFormats-numberSystem-{nu}"]["standard"]
    curp = num[f"currencyFormats-numberSystem-{nu}"]["standard"]
    hg = num.get("minimumGroupingDigits", 1)

    comp = {}
    for disp in ("short", "long"):
        src = num[f"decimalFormats-numberSystem-{nu}"].get(disp, {}).get("decimalFormat", {})
        groups = []
        for e in range(3, 16):
            div = 10 ** e
            pairs = []
            for k, v in src.items():
                m = re.match(rf"^{div}(?:-count)?-([a-z]+)$", k)
                if m and m.group(1) in CAT:
                    pairs.append((CAT[m.group(1)], v))
            if pairs and len({p[1] for p in pairs}) == 1:
                keep = [p for p in pairs if p[0] in (0, 1, 4, 5)]
                pairs = keep[:1]
            groups.append(cgrp(pairs))
        comp[disp] = groups   # 13 consecutive cgrp indices

    def rules_for(table, t):
        for cand in (t, t.split("-")[0]):
            if cand in table:
                m = {k.replace("pluralRule-count-", ""): v for k, v in table[cand].items()}
                r = ruleset(m)
                if r != 0xFFFF: return r
        return 0xFFFF
    card = rules_for(plurals, tag)
    ordi = rules_for(ordinals, tag)

    mo = dts["months"]; dy = dts["days"]
    mo_offs = [parr([mo[s][w][str(i)] for i in range(1, 13)])
               for s in ("format", "stand-alone") for w in ("wide", "abbreviated", "narrow")]
    dy_offs = [parr([dy["format"][w][k] for k in ("sun", "mon", "tue", "wed", "thu", "fri", "sat")])
               for w in ("wide", "abbreviated", "narrow")]
    dy_offs.append(parr([dy["stand-alone"]["wide"][k] for k in ("sun", "mon", "tue", "wed", "thu", "fri", "sat")]))
    dp = dts["dayPeriods"]["format"]["abbreviated"]
    per_off = parr([dp.get("am", "AM"), dp.get("pm", "PM"), dp.get("noon", "noon"), dp.get("midnight", "midnight")])
    er = dts["eras"]
    era_off = parr([er["eraAbbr"]["0"], er["eraAbbr"]["1"],
                  er.get("eraWide", {}).get("0", "Before Christ"),
                  er.get("eraWide", {}).get("1", "Anno Domini")])
    df_off = parr([dts["dateFormats"][k] for k in ("full", "long", "medium", "short")])
    tf_off = parr([dts["timeFormats"][k] for k in ("full", "long", "medium", "short")])
    dtf = dts["dateTimeFormats"]
    glue_off = parr([dtf[k] for k in ("full", "long", "medium", "short")])

    af = []
    for k, v in sorted(dtf["availableFormats"].items()):
        if not ok_pattern(v): continue
        if set(pattern_chars(v)) - ALLOWED_SYMS: continue
        af.append((sk(k), po(v)))

    lcur = []
    for code in CURRENCIES:
        e = curs.get(code)
        if not e: continue
        pats = []
        for k, v in e.items():
            m = re.match(r"^displayName-count-([a-z]+)$", k)
            if m and m.group(1) in CAT: pats.append((CAT[m.group(1)], v))
        if pats and len({p[1] for p in pats}) == 1:
            keep = [p for p in pats if p[0] in (0, 1, 4, 5)]
            pats = keep[:1]
        lcur.append({"ci": (ord(code[0]) << 24) | (ord(code[1]) << 16) | (ord(code[2]) << 8),
                     "sym": po(e.get("symbol", code)),
                     "narrow": po(e.get("symbol-alt-narrow", e.get("symbol", code))),
                     "name": po(e["displayName"]) if e.get("displayName") else 0xFFFF,
                     "grp": cgrp(pats)})
    lcur.sort(key=lambda x: x["ci"])

    lunit = []
    if unt:
        tbl = unt["long"]
        tbl_s = unt.get("short", {})
        for uid in UNITS:
            key = next((k for k in unit_keys(uid) if k in tbl), None)
            if not key: continue
            u = tbl[key]
            pats = []
            for k, v in u.items():
                m = re.match(r"^unitPattern-count-([a-z]+)$", k)
                if m and m.group(1) in CAT: pats.append((CAT[m.group(1)], v))
            if not pats: continue
            if len({p[1] for p in pats}) == 1:
                keep = [p for p in pats if p[0] in (0, 1, 4, 5)]
                pats = keep[:1]
            spats = []
            us = tbl_s.get(key)
            if us:
                for k, v in us.items():
                    m = re.match(r"^unitPattern-count-([a-z]+)$", k)
                    if m and m.group(1) in CAT: spats.append((CAT[m.group(1)], v))
                if spats and len({p[1] for p in spats}) == 1:
                    keep = [p for p in spats if p[0] in (0, 1, 4, 5)]
                    spats = keep[:1]
            lunit.append({"ui": UNITS.index(uid),
                          "disp": po(u["displayName"]) if u.get("displayName") else 0xFFFF,
                          "grp": cgrp(pats), "sgrp": cgrp(spats)})
        lunit.sort(key=lambda x: x["ui"])

    lp_off = 0xFFFF  # listPatterns are collected in the second pass below

    fgrps = []
    if fld:
        for base in RTF_FIELDS:
            for w in ("", "-short", "-narrow"):
                f = fld.get(base + w)
                if not f: fgrps.append(None); continue
                rel = [po(f[f"relative-type-{n}"]) if f.get(f"relative-type-{n}") else 0xFFFF for n in (-1, 0, 1)]
                def rtp(d):
                    pairs = []
                    for k, v in d.items():
                        m = re.match(r"^relativeTimePattern-count-([a-z]+)$", k)
                        if m and m.group(1) in CAT: pairs.append((CAT[m.group(1)], v))
                    return cgrp(pairs)
                fgrps.append((rel[0], rel[1], rel[2], rtp(f.get("relativeTime-type-future", {})),
                              rtp(f.get("relativeTime-type-past", {}))))

    locales.append(dict(tag=tag, nu=NUMSYS.index(nu), hc=hc_of([dts["timeFormats"][k] for k in ("full", "long", "medium", "short")][3]),
                        hg=hg, sym=[po(s) for s in syms(sym)], dec=po(std), pct=po(pct), sci=po(sci), cur_pat=po(curp),
                        card=card, ord=ordi, comp=comp, mo=mo_offs, dy=dy_offs,
                        per=per_off, era=era_off, df=df_off, tf=tf_off, glue=glue_off,
                        af=af, cur=lcur, unit=lunit, lp=lp_off, fgrps=fgrps))
if miss:
    print("MISSING locale files:", miss)

# ---------------------------------------------------------------- numbering systems
nsys_rows = []
for n in NUMSYS:
    dig = nsys_all.get(n, {}).get("_digits") or "0123456789"
    nsys_rows.append((n, dig))

frac_rows = []
for code, e in sorted(curfrac.items()):
    if code.startswith("_"): continue
    d = e.get("_digits")
    if d == "inde": continue
    frac_rows.append((code, int(d) if d is not None else 2))
curfrac_default = int(curfrac.get("DEFAULT", {}).get("_digits", "2"))

# ---------------------------------------------------------------- flatten global arrays
af_u16 = []
af_loc_off = []
for loc in locales:
    af_loc_off.append(len(af_u16))
    for s, p in loc["af"]:
        af_u16.extend([s, p])

lc_arr, lc_loc = [], []
for loc in locales:
    lc_loc.append(len(lc_arr))
    for e in loc["cur"]:
        lc_arr.append((e["ci"], e["sym"], e["narrow"], e["name"], e["grp"]))

lu_arr, lu_loc = [], []
for loc in locales:
    lu_loc.append(len(lu_arr))
    for e in loc["unit"]:
        lu_arr.append((e["ui"], e["disp"], e["grp"], e["sgrp"]))

fg_arr, fg_loc = [], []
for loc in locales:
    fg_loc.append(len(fg_arr))
    if not loc["fgrps"]:
        fg_loc[-1] = 0xFFFF
        continue
    for g in loc["fgrps"]:
        if g is None:
            fg_arr.append((0xFFFF, 0xFFFF, 0xFFFF, 0xFFFF, 0, 0xFFFF, 0))
        else:
            fo, fn = cgrp_view(g[3]); po_, pn = cgrp_view(g[4])
            fg_arr.append((g[0], g[1], g[2], fo, fn, po_, pn))

# listPattern per-locale offsets (redo cleanly: 5 groups x 4 pool offsets)
lp_u16 = []
for loc in locales:
    msc = None
    tag = loc["tag"]
    p = os.path.join(CLDR, f"cldr-misc-full/main/{tag}/listPatterns.json")
    if os.path.exists(p):
        msc = load(f"cldr-misc-full/main/{tag}/listPatterns.json")["main"][tag]["listPatterns"]
    if not msc:
        loc["lp"] = 0xFFFF
        continue
    offs = []
    for typ in ("standard", "or", "unit", "unit-short", "unit-narrow"):
        g = msc.get(f"listPattern-type-{typ}") or (msc.get("listPattern") if typ == "standard" else None)
        if not g: offs = None; break
        offs.append(parr([g.get("start", g.get("end", "{0}, {1}")),
                          g.get("middle", g.get("end", "{0}, {1}")),
                          g["end"], g.get("pair", g.get("2", g["end"]))]))
    if not offs:
        loc["lp"] = 0xFFFF
    else:
        loc["lp"] = len(lp_u16)
        lp_u16.extend(offs)

# ---------------------------------------------------------------- emit C
def cesc(s):
    out = []
    if isinstance(s, str): s = s.encode("utf-8")
    for ch in s:
        if ch == 0x22: out.append('\\"')
        elif ch == 0x5C: out.append("\\\\")
        elif 32 <= ch < 127: out.append(chr(ch))
        else: out.append(f"\\{ch // 64}{(ch // 8) % 8}{ch % 8}")
    return '"' + "".join(out) + '"'

L = []
A = L.append
try:
    ver = json.load(open(os.path.join(CLDR, "cldr-core", "cldr-packages.json")))["cldrVersion"]
except Exception:
    ver = "49"
A(f"""// intl_data.c — CLDR data for the Intl builtins (generated by tools/gen_intl.py
// from CLDR {ver}; do not edit by hand).
// CLDR is third-party DATA under the Unicode License (same class as the UCD
// tables in unicode_data.c); the layout and this generator are ours.
#include "intl.h"

#define INTL_NLOC {len(locales)}
#define INTL_NSYS {len(NUMSYS)}
#define INTL_NSKEL {len(skels)}
#define INTL_NRS {len(rs_rows)}
#define INTL_NUNIT {len(UNITS)}
""")

def emit_u16_array(name, vals):
    A(f"const uint16_t {name}[] = {{")
    row = ""
    for v in vals:
        t = f"{v},"
        if len(row) + len(t) > 108: A("    " + row); row = ""
        row += t + " "
    if row: A("    " + row)
    A("};")
    A("")

def emit_u32_array(name, vals):
    A(f"const unsigned {name}[] = {{")
    row = ""
    for v in vals:
        t = f"{v},"
        if len(row) + len(t) > 100: A("    " + row); row = ""
        row += t + " "
    if row: A("    " + row)
    A("};")
    A("")

# pool
A("const char intl_pool[] =")
line = ""
for s in pool_buf:
    tok = cesc(s + b"\0")   # each entry keeps its NUL terminator (the offsets assume it)
    if len(line) + len(tok) + 1 > 110:
        A("    " + line); line = ""
    line += tok + " "
if line: A("    " + line)
A(";")
A("")

# locale tags + main records
A("const struct intl_loc intl_locales[INTL_NLOC] = {")
for li, loc in enumerate(locales):
    mo = ",".join(str(o) for o in loc["mo"])
    dy = ",".join(str(o) for o in loc["dy"])
    sy = ",".join(str(o) for o in loc["sym"])
    fld = fg_loc[li]
    A(f'{{ "{loc["tag"]}", {loc["nu"]}, {loc["hc"]}, {loc["hg"]}, 0,')
    A(f'  {{ {sy} }},')
    A(f'  {loc["dec"]}, {loc["pct"]}, {loc["sci"]}, {loc["cur_pat"]},')
    A(f'  {loc["card"]}, {loc["ord"]}, {loc["comp"]["short"][0]}, {loc["comp"]["long"][0]},')
    A(f'  {{ {mo} }},')
    A(f'  {{ {dy} }},')
    A(f'  {loc["per"]}, {loc["era"]}, {loc["df"]}, {loc["tf"]}, {loc["glue"]},')
    A(f'  {af_loc_off[li]}, {len(loc["af"])},')
    A(f'  {lc_loc[li]}, {len(loc["cur"])}, {lu_loc[li]}, {len(loc["unit"])}, {loc["lp"]}, {fld} }},')
A("};")
A("")

# skeletons
A("const char* const intl_skel[INTL_NSKEL] = {")
for s in sorted(skels, key=skels.get):
    A(f"    {cesc(s)},")
A("};")
A("")
emit_u32_array("intl_af", af_u16)

# plural rulesets
A("const struct intl_rset intl_rs[INTL_NRS] = {")
rs_u16 = []
for mask, offs in rs_rows:
    A(f"    {{ {mask}, {len(rs_u16)}, {len(offs)} }},")
    rs_u16.extend(offs)
A("};")
A("")
emit_u32_array("intl_rs_off", rs_u16)

# cpairs + groups
A("const struct intl_cpair intl_cp[] = {")
for c, p in cpairs:
    A(f"    {{ {c}, {p} }},")
A("};")
A("const struct intl_cgrp intl_cg[] = {")
for off, n in cgrps:
    A(f"    {{ {off}, {n} }},")
A("};")
A("")

# numbering systems
A("const struct intl_nsys intl_nsys[INTL_NSYS] = {")
for n, dig in nsys_rows:
    A(f'    {{ "{n}", {cesc(dig)} }},')
A("};")
A("")

# likely subtags
A("const struct intl_likely intl_likely[] = {")
for k, v in sorted(sup.items()):
    A(f'    {{ "{k.lower()}", "{v.lower()}" }},')
A("};")
A("")

for name, rows in (("lang", lang_alias), ("terr", terr_alias), ("scr", scr_alias)):
    A(f"const struct intl_alias intl_alias_{name}[] = {{")
    for a, b in rows:
        A(f'    {{ "{a}", "{b}" }},')
    A("};")
    A("")

# currency fractions
A("const struct intl_curfrac intl_curfrac[] = {")
for code, d in frac_rows:
    A(f'    {{ "{code}", {d} }},')
A("};")
A(f"#define INTL_CURFRAC_DEFAULT {curfrac_default}")
A("")

# per-locale currency + units
A("const struct intl_lcur intl_lcur[] = {")
if lc_arr:
    for ci, symv, narrow, name, grp in lc_arr:
        A(f"    {{ {ci}, {symv}, {narrow}, {name}, {grp} }},")
else:
    A("    { 0, 0, 0, 0, 0xFFFF },")
A("};")
A("const struct intl_lunit intl_lunit[] = {")
if lu_arr:
    for ui, disp, grp, sgrp in lu_arr:
        A(f"    {{ {ui}, {disp}, {grp}, {sgrp} }},")
else:
    A("    { 0, 0, 0xFFFF, 0xFFFF },")
A("};")
A("")
A("const char* const intl_unit_id[INTL_NUNIT] = {")
for u in UNITS:
    A(f'    "{u}",')
A("};")
A("")

# date field groups (8 fields x 3 widths per locale, consecutive)
A("const struct intl_fgrp intl_fg[] = {")
for r0, r1, r2, fo, fn, po_, pn in fg_arr:
    A(f"    {{ {{ {r0},{r1},{r2} }}, {fo},{fn}, {po_},{pn} }},")
A("};")
A("")
emit_u32_array("intl_lp", lp_u16 if lp_u16 else [0xFFFF])

